print("partial+full ok")

p=mk()
try: refund(p,Decimal("100.01"),T0); print("FAIL")
except BillingError as e: print("over:",e.code)
p=mk("authorized")
try: refund(p,Decimal("1"),T0); print("FAIL")
except BillingError as e: print("state:",e.code)
p=mk()
try: refund(p,Decimal("0"),T0); print("FAIL")
except BillingError as e: print("zero:",e.code)
p=mk()
try: refund(p,Decimal("1.005"),T0); print("rounded:",p.refunded_amount)
except BillingError as e: print(e)
